'use client'

import { MathJax, MathJaxContext } from 'better-react-mathjax'
import type { ComponentProps, ReactNode } from 'react'

export function CalculatorMathProvider({ children }: { children: ReactNode }) {
  return (
    <MathJaxContext version={4} config={{ startup: { typeset: false }, options: { enableMenu: false } }}>
      {children}
    </MathJaxContext>
  )
}

export function MathExpression({ mathml, ...props }: { mathml: string } & ComponentProps<'span'>) {
  const text = /^\s*<math(?:\s|>)/.test(mathml)
    ? mathml
    : `<math xmlns="http://www.w3.org/1998/Math/MathML">${mathml}</math>`

  return (
    <MathJax
      key={text}
      {...props}
      inline
      hideUntilTypeset="first"
      renderMode="pre"
      typesettingOptions={{ fn: 'mathml2chtmlPromise' }}
      text={text}
    />
  )
}

.calculator-math mjx-container {
  margin: 0;
}

.calculator-operation-label {
  display: inline-flex;
  align-items: center;
}

.calculator-cell-grid {
  min-width: 0;
  max-width: 100%;
  overflow: auto;
  max-height: 15rem;
  border: 1px solid var(--border);
}
.calculator-cell-grid table {
  width: 100%;
  min-width: 28rem;
  table-layout: fixed;
  border-collapse: separate;
  border-spacing: 0;
  font-size: 0.8125rem;
}
.calculator-cell-grid th,
.calculator-cell-grid td {
  height: 2.5rem;
  padding: 0.375rem 0.625rem;
  border-right: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  text-align: left;
  font-weight: normal;
}
.calculator-cell-grid th {
  background: var(--muted);
  color: var(--muted-foreground);
  font-size: 0.6875rem;
}
.calculator-cell-grid thead th {
  position: sticky;
  top: 0;
  z-index: 1;
}
.calculator-cell-grid tbody th { text-align: center; }
.calculator-cell-grid tr > :last-child { border-right: 0; }
.calculator-cell-grid tbody tr:last-child > * { border-bottom: 0; }
.calculator-column-letter { display: block; font-weight: 600; }
.calculator-cell-grid td[data-selected] { background: var(--accent); }
.calculator-cell-grid td:focus,
.calculator-cell-grid td:focus-within {
  outline: 2px solid var(--primary);
  outline-offset: -2px;
}
.calculator-cell-content {
  display: flex;
  align-items: center;
  min-height: 1.75rem;
  overflow: hidden;
  white-space: nowrap;
}

.calculator-cell-grid td.calculator-computed-cell {
  background: var(--muted);
  color: var(--muted-foreground);
}

import type { RelationAst } from '@/registry/calculator/lib/dsl/ast'
import type { SolverResult } from '@/registry/calculator/lib/solver/protocol'

export type Relation = {
  id: string
  source: string
  ast: RelationAst
  createdAt: number
  enabled: boolean
}

export type VariableInput = {
  id: string
  name: string
  source: string
}

export type SolverState =
  | { phase: 'idle' }
  | { phase: 'diagnostic'; code: 'no-relations'; message: string }
  | { phase: 'loading'; requestId: string }
  | { phase: 'complete'; requestId: string; result: SolverResult }

export type CalculatorState = {
  source: string
  relations: Relation[]
  variables: VariableInput[]
  editingId: string | null
  solver: SolverState
  helpOpen: boolean
}

export const initialCalculatorState: CalculatorState = {
  source: '',
  relations: [],
  variables: [],
  editingId: null,
  solver: { phase: 'idle' },
  helpOpen: false,
}

export type CalculatorAction =
  | { type: 'variable-saved'; variable: VariableInput }
  | { type: 'variable-deleted'; id: string }
  | { type: 'library-added'; relations: Relation[] }
  | { type: 'source-changed'; source: string }
  | {
      type: 'save'
      id: string
      source: string
      ast: RelationAst
      now: number
    }
  | { type: 'edit'; id: string }
  | { type: 'delete'; id: string }
  | { type: 'enabled-changed'; id: string; enabled: boolean }
  | { type: 'clear-editor' }
  | { type: 'clear-all' }
  | { type: 'help-changed'; open: boolean }
  | {
      type: 'local-diagnostic'
      code: 'no-relations'
      message: string
    }
  | { type: 'solve-started'; requestId: string }
  | {
      type: 'solve-finished'
      requestId: string
      result: SolverResult
    }

export type OperationItem = {
  id: string
  label: string
  template: string
  shortcut: string
}

export type OperationGroup = {
  name: 'Arithmetic' | 'Scientific' | 'Algebra' | 'Calculus' | 'Probability'
  shortcut: string
  items: OperationItem[]
}

export const OPERATION_GROUPS: OperationGroup[] = [
  {
    name: 'Arithmetic',
    shortcut: 'r',
    items: [
      { id: 'add', shortcut: 'p', label: '+', template: '□ + ' },
