export type PreflightResult =
  | { ok: true; equationCount: number; variableCount: number }
  | {
      ok: false
      status: 'overdefined'
      equationCount: number
      variableCount: number
      message: string
    }

export function preflight(relations: RelationAst[]): PreflightResult {
  const equationCount = relations.filter(
    (relation) => relation.kind === 'equation',
  ).length
  const variableCount = collectEquationSymbols(relations).length

  if (!hasProbability(relations) && !hasMatrixValues(relations) && equationCount > variableCount) {
    return {
      ok: false,
      status: 'overdefined',
      equationCount,
      variableCount,
      message: `${equationCount} equation${equationCount === 1 ? '' : 's'} exceeds ${variableCount} distinct unknowns.`,
    }
  }

  return { ok: true, equationCount, variableCount }
}

import type { RelationAst } from '@/registry/calculator/lib/dsl/ast'

export type DisplayValue = {
  exact: string
  mathml: string
  approximate?: string
}

export type SolutionResult = {
  assignments: Record<string, DisplayValue>
  queries: DisplayValue[]
}

export type SolverResult =
  | {
      status: 'solved'
      variables: string[]
      solutions: SolutionResult[]
    }
  | { status: 'no-solution'; message: string }
  | { status: 'underdetermined'; symbols: string[]; message: string }
  | {
      status: 'overdefined'
      equationCount: number
      variableCount: number
      message: string
    }
  | { status: 'unresolved'; message: string; detail?: string }
  | { status: 'unsupported'; message: string; feature?: string }
  | { status: 'error'; message: string }

export type SolverMode = 'system' | 'symbolic' | 'workspace'

export type SolverRequest = {
  type: 'solve'
  id: string
  relations: RelationAst[]
  mode: SolverMode
}

export type SolverWorkerMessage =
  | { type: 'ready' }
  | { type: 'init-error'; message: string }
  | { type: 'result'; id: string; result: SolverResult }

import { hasProbability, prepareProbability } from '@/registry/calculator/lib/probability'
import { preflight } from '@/registry/calculator/lib/solver/preflight'
import type { RelationAst } from '@/registry/calculator/lib/dsl/ast'
import { SOLVER_WORKER_SOURCE } from '@/registry/calculator/lib/generated/solver-worker-source'
import type {
  SolverRequest,
  SolverMode,
  SolverResult,
  SolverWorkerMessage,
} from '@/registry/calculator/lib/solver/protocol'

export type SolverEngineSnapshot =
  | { phase: 'idle' }
  | { phase: 'loading' }
  | { phase: 'ready' }
  | { phase: 'failed'; message: string }

export interface WorkerLike {
  onmessage: ((event: MessageEvent<SolverWorkerMessage>) => void) | null
  onerror: ((event: ErrorEvent) => void) | null
  postMessage(message: SolverRequest): void
  terminate(): void
}

export interface SolverClient {
  start(): void
  solve(relations: RelationAst[], mode?: SolverMode): Promise<SolverResult>
  getSnapshot(): SolverEngineSnapshot
  subscribe(listener: () => void): () => void
  retry(): void
  dispose(): void
}

type WorkerFactory = () => WorkerLike

type ActiveRequest = {
  request: SolverRequest
  resolve(result: SolverResult): void
  posted: boolean
}

const defaultWorkerFactory: WorkerFactory = () => {
  const workerUrl = URL.createObjectURL(
    new Blob([SOLVER_WORKER_SOURCE], { type: 'text/javascript' }),
  )
  const worker = new Worker(workerUrl, { type: 'module' })
  const terminate = worker.terminate.bind(worker)
  worker.terminate = () => {
    URL.revokeObjectURL(workerUrl)
    terminate()
  }
  return worker
}

export function createSolverClient(
  workerFactory: WorkerFactory = defaultWorkerFactory,
): SolverClient {
  let worker: WorkerLike | null = null
  let snapshot: SolverEngineSnapshot = { phase: 'idle' }
  let sequence = 0
  const listeners = new Set<() => void>()
  let queued: SolverRequest | null = null
  let active: ActiveRequest | null = null

  function publish(next: SolverEngineSnapshot): void {
    snapshot = next
    for (const listener of listeners) listener()
  }

  function settleActive(message: string): void {
    active?.resolve({ status: 'error', message })
    active = null
    queued = null
  }

  function handleMessage(
    source: WorkerLike,
    message: SolverWorkerMessage,
  ): void {
    if (source !== worker) return
    if (message.type === 'ready') {
      publish({ phase: 'ready' })
      if (queued && active?.request.id === queued.id) {
        active.posted = true
        source.postMessage(queued)
        queued = null
      }
      return
    }
    if (message.type === 'init-error') {
      publish({ phase: 'failed', message: message.message })
      settleActive(message.message)
      return
    }
    if (!active || active.request.id !== message.id) return
    const { resolve } = active
    active = null
    resolve(message.result)
  }

  function startWorker(): void {
    publish({ phase: 'loading' })
    try {
      const nextWorker = workerFactory()
      worker = nextWorker
      nextWorker.onmessage = (event) => handleMessage(nextWorker, event.data)
      nextWorker.onerror = (event) => {
        if (nextWorker !== worker) return
        const message = event.message || 'The solver worker stopped unexpectedly.'
        publish({ phase: 'failed', message })
        settleActive(message)
      }
    } catch (error) {
      worker = null
      const message =
        error instanceof Error ? error.message : 'The solver worker could not start.'
      publish({ phase: 'failed', message })
      settleActive(message)
    }
  }

  return {
    start() {
      if (!worker) startWorker()
    },
    solve(relations, mode = 'system') {
      if (active) {
        const restartWorker = active.posted
        settleActive('This calculation was superseded by a newer request.')
        if (restartWorker) {
          worker?.terminate()
          worker = null
        }
      }
      let finish = (result: SolverResult) => result
      if (hasProbability(relations)) {
        try {
          const prepared = prepareProbability(relations)
          if (prepared.result) return Promise.resolve(prepared.result)
          relations = prepared.relations
          finish = prepared.finish
          const validation = preflight(relations)
          if (!validation.ok) return Promise.resolve({ ...validation, status: 'overdefined' } as SolverResult)
        } catch (error) {
          return Promise.resolve({ status: 'unsupported', message: error instanceof Error ? error.message : 'Unable to evaluate probability.' } as SolverResult)
        }
      }
      if (snapshot.phase === 'failed') {
        worker?.terminate()
        worker = null
      }
      const request: SolverRequest = {
        type: 'solve',
        id: `solve-${Date.now()}-${++sequence}`,
        relations,
        mode,
      }
      const promise = new Promise<SolverResult>((resolve) => {
        active = { request, resolve: result => resolve(finish(result)), posted: false }
      })
      if (!worker) startWorker()
      if (!active || active.request.id !== request.id) return promise
      if (worker && snapshot.phase === 'ready') {
        active.posted = true
        worker.postMessage(request)
      } else if (snapshot.phase !== 'failed') {
        queued = request
      }
      return promise
    },
    getSnapshot() {
      return snapshot
    },
    subscribe(listener) {
      listeners.add(listener)
      return () => listeners.delete(listener)
    },
    retry() {
      worker?.terminate()
      worker = null
      settleActive('The solver restarted before the calculation finished.')
      startWorker()
    },
    dispose() {
      worker?.terminate()
      worker = null
      settleActive('The solver was closed before the calculation finished.')
      publish({ phase: 'idle' })
      listeners.clear()
    },
  }
}

"""Trusted SymPy adapter for validated calculator AST payloads.

This module deliberately contains no parsing or evaluation of source strings.
Every accepted operation is selected from closed dispatch tables below.
"""

import sympy as sp


class UnsupportedFeature(Exception):
    """Raised when a valid payload asks for a capability outside V1."""


class RealDomainError(Exception):
    """Raised when a valid operation produces a non-real value in real mode."""


class UndefinedDomainError(Exception):
    """Raised when an operation produces an undefined closed value."""


class UnresolvedValueError(Exception):
    """Raised when SymPy cannot establish whether a closed value is real."""


SYMBOLIC_QUERY_OPERATIONS = {
    "simplify",
    "expand",
    "factor",
    "diff",
    "integrate",
    "limit",
    "grad", "jacobian", "div", "curl", "hessian",
}

CALCULUS_BINDING_INDEX = {"diff": 1, "integrate": 1, "limit": 1}


def _collect_symbols(node, names):
    kind = node.get("kind") if isinstance(node, dict) else None
    if kind == "array":
        for item in node["items"]:
            _collect_symbols(item, names)
        return
    if kind == "symbol":
        names.add(str(node["name"]).lower())
        return
    if kind in {"number", "constant"}:
        return
    if kind in {"unary", "factorial"}:
        _collect_symbols(node["operand"], names)
        return
    if kind == "binary":
        _collect_symbols(node["left"], names)
        _collect_symbols(node["right"], names)
        return
    if kind == "call":
        binding_index = CALCULUS_BINDING_INDEX.get(node.get("name"))
        for index, argument in enumerate(node.get("args", [])):
            if index != binding_index:
                _collect_symbols(argument, names)
        return
    raise UnsupportedFeature(f"Unsupported AST node: {kind or 'unknown'}")


def _equation_symbol_names(relations):
    names = set()
    for relation in relations:
        if relation.get("kind") != "equation":
            continue
        _collect_symbols(relation["left"], names)
        _collect_symbols(relation["right"], names)
    return sorted(names)


def _number(value):
    try:
        return sp.Rational(str(value))
    except (TypeError, ValueError) as error:
        raise UnsupportedFeature(f"Unsupported number literal: {value}") from error


def _require_symbol(value, operation):
    if not isinstance(value, sp.Symbol):
        raise UnsupportedFeature(f"{operation} requires a variable as its second argument")
    return value


def _build_allowed_call(name, raw_args, symbols):
    binding = 1 if name in {"diff", "integrate", "limit", "grad", "jacobian", "div", "curl", "hessian"} else None
    scope = symbols
    bound = set()
    if binding is not None and len(raw_args) > binding:
        _collect_symbols(raw_args[binding], bound)
        if hasattr(symbols, "without"):
            scope = symbols.without(bound)
    args = [build_expr(argument, {} if index == binding else scope) for index, argument in enumerate(raw_args)]
    result = _apply_allowed_call(name, args)
    if scope is not symbols and name != "limit":
        substitutions = {sp.Symbol(key, real=True): symbols.setdefault(key, sp.Symbol(key, real=True)) for key in bound}
        if any(isinstance(value, sp.MatrixBase) for value in substitutions.values()):
            raise UnsupportedFeature("Calculus variables must have scalar values")
        result = result.subs(substitutions, simultaneous=True)
    return result


def _apply_allowed_call(name, args):
    if name in {"dot", "cross", "norm", "unit", "transpose", "det", "inv", "trace", "rank", "linsolve", "grad", "jacobian", "div", "curl", "hessian"}:
        return _matrix_call(name, args)
    unary_calls = {
        "sqrt": sp.sqrt,
        "abs": sp.Abs,
        "exp": sp.exp,
        "ln": sp.log,
        "log": sp.log,
        "sin": sp.sin,
        "cos": sp.cos,
        "tan": sp.tan,
        "asin": sp.asin,
        "acos": sp.acos,
        "atan": sp.atan,
        "sinh": sp.sinh,
        "cosh": sp.cosh,
        "tanh": sp.tanh,
        "simplify": sp.simplify,
        "expand": sp.expand,
        "factor": sp.factor,
    }
    if name in unary_calls and len(args) == 1:
        return unary_calls[name](args[0])
    if name == "log10" and len(args) == 1:
        return sp.log(args[0], 10)
    if name == "diff" and len(args) == 2:
        return sp.diff(args[0], _require_symbol(args[1], name))
    if name == "integrate" and len(args) == 2:
        return sp.integrate(args[0], _require_symbol(args[1], name))
    if name == "limit" and len(args) == 3:
        variable = _require_symbol(args[1], name)
        return args[0].applyfunc(lambda entry: sp.limit(entry, variable, args[2])) if isinstance(args[0], sp.MatrixBase) else sp.limit(args[0], variable, args[2])
    raise UnsupportedFeature(f"Unsupported function or argument count: {name}")


def build_expr(node, symbols):
    if not isinstance(node, dict):
        raise UnsupportedFeature("AST nodes must be objects")
    kind = node.get("kind")
    if kind == "array":
        items = node.get("items", [])
        if not items:
            raise UnsupportedFeature("Vectors and matrices cannot be empty")
        if any(item.get("kind") == "array" for item in items):
            if not all(item.get("kind") == "array" and len(item["items"]) == len(items[0]["items"]) for item in items):
                raise UnsupportedFeature("Matrices require equally sized rows")
            values = [[build_expr(entry, symbols) for entry in item["items"]] for item in items]
        else:
            values = [[build_expr(item, symbols)] for item in items]
        if any(isinstance(entry, sp.MatrixBase) for row in values for entry in row):
            raise UnsupportedFeature("Vector and matrix entries must be scalars")
        return sp.ImmutableMatrix(values)
    if kind == "number":
        return _number(node.get("value"))
    if kind == "symbol":
        name = str(node.get("name", "")).lower()
        if not name:
            raise UnsupportedFeature("Symbols must have a name")
        return symbols.setdefault(name, sp.Symbol(name, real=True))
    if kind == "constant":
        constants = {"pi": sp.pi, "e": sp.E}
        name = node.get("name")
        if name not in constants:
            raise UnsupportedFeature(f"Unsupported constant: {name}")
        return constants[name]
    if kind == "unary":
        operand = build_expr(node["operand"], symbols)
        if node.get("operator") == "+":
            return operand
        if node.get("operator") == "-":
            return -operand
        raise UnsupportedFeature(f"Unsupported unary operator: {node.get('operator')}")
    if kind == "binary":
        left = build_expr(node["left"], symbols)
        right = build_expr(node["right"], symbols)
        operator = node.get("operator")
        lm, rm = isinstance(left, sp.MatrixBase), isinstance(right, sp.MatrixBase)
        if lm or rm:
            if operator in {"+", "-"} and (not lm or not rm or left.shape != right.shape):
                raise UnsupportedFeature("Addition and subtraction require matching vector or matrix dimensions")
            if operator == "*" and lm and rm and left.cols != right.rows:
                raise UnsupportedFeature(f"Cannot multiply {left.rows}×{left.cols} by {right.rows}×{right.cols}; use dot(u,v) for a dot product")
            if operator == "/" and rm:
                raise UnsupportedFeature("Division requires a scalar divisor; use inv or linsolve")
            if operator == "^" and (not lm or rm or right.is_Integer is not True or left.rows != left.cols):
                raise UnsupportedFeature("Matrix powers require a square matrix and an integer exponent")
        if operator == "+":
            return left + right
        if operator == "-":
            return left - right
        if operator == "*":
            return left * right
        if operator == "/":
            return left / right
        if operator == "^":
            return left**right
        raise UnsupportedFeature(f"Unsupported binary operator: {operator}")
    if kind == "factorial":
        return sp.factorial(build_expr(node["operand"], symbols))
    if kind == "call":
        return _build_allowed_call(node.get("name"), node.get("args", []), symbols)
    raise UnsupportedFeature(f"Unsupported AST node: {kind or 'unknown'}")


def _underdetermined(symbols):
    names = sorted({str(symbol) for symbol in symbols})
    return {
        "status": "underdetermined",
        "symbols": names,
        "message": "The saved relations leave "
        + (", ".join(names) if names else "one or more values")
        + " undetermined.",
    }


def _set_has_continuum(value):
    if value in {sp.S.Reals, sp.S.Complexes, sp.S.UniversalSet}:
        return True
    if isinstance(value, sp.Interval):
        return True
    if isinstance(value, sp.Union):
        return any(_set_has_continuum(argument) for argument in value.args)
    return False


def _classify_nested_sets(values, variables):
    nested_sets = [value for value in values if isinstance(value, sp.Set)]
    if not nested_sets:
        return None
    if any(value == sp.EmptySet for value in nested_sets):
        return {"status": "no-solution", "message": "No real solution exists."}
    if any(_set_has_continuum(value) for value in nested_sets):
        return _underdetermined(variables)
    return {
        "status": "unresolved",
        "message": "SymPy returned a non-finite solution representation.",
        "detail": str(tuple(nested_sets)),
    }


def classify_solution_set(solution_set, variables, allow_symbolic=False):
    """Classify a SymPy set without conflating unknown and empty results."""
    if solution_set is sp.EmptySet or solution_set == sp.EmptySet:
        return {"status": "no-solution", "message": "No real solution exists."}
    if isinstance(solution_set, sp.ConditionSet):
        return {
            "status": "unresolved",
            "message": "SymPy could not resolve this system to a finite solution set.",
            "detail": str(solution_set),
        }
    if not isinstance(solution_set, sp.FiniteSet):
        return {
            "status": "unresolved",
            "message": "SymPy returned a non-finite solution representation.",
            "detail": str(solution_set),
        }

    candidates = []
    for item in solution_set:
        values = tuple(item) if isinstance(item, (tuple, sp.Tuple)) else (item,)
        if len(values) != len(variables):
            return _underdetermined(variables)
        nested_classification = _classify_nested_sets(values, variables)
        if nested_classification:
            if nested_classification["status"] == "no-solution":
                continue
            return nested_classification
        if any(value.free_symbols for value in values) and not allow_symbolic:
            return _underdetermined(variables)
        if any(value.is_real is False for value in values):
            continue
        candidates.append(values)

    if not candidates:
        return {"status": "no-solution", "message": "No real solution exists."}

    candidates.sort(key=sp.default_sort_key)
    deduplicated = []
    seen = set()
    for candidate in candidates:
        key = tuple(sp.srepr(sp.simplify(value)) for value in candidate)
        if key not in seen:
            seen.add(key)
            deduplicated.append(candidate)
    return {"status": "solved", "raw_solutions": deduplicated}


def _display_value(value):
    exact_value = value
    display = {
        "exact": str(exact_value),
        "mathml": sp.mathml(exact_value, printer="presentation"),
    }
    if not isinstance(exact_value, sp.MatrixBase) and not exact_value.free_symbols and exact_value.is_number and not exact_value.is_Integer:
        approximate = str(sp.N(exact_value, 12))
        if approximate != display["exact"]:
            display["approximate"] = approximate
    return display


def _query_allows_symbolic_result(relation):
    expression = relation.get("expression", {})
    return (
        expression.get("kind") == "call"
        and expression.get("name") in SYMBOLIC_QUERY_OPERATIONS
    )


def _evaluate_queries(query_rows, symbols, assignments, allow_symbolic=False):
    values = []
    unresolved_symbols = set()
    for relation in query_rows:
        value = build_expr(relation["expression"], symbols).subs(assignments, simultaneous=True)
        if not _query_allows_symbolic_result(relation):
            value = sp.simplify(value)
        if value.has(sp.nan, sp.zoo):
            raise UndefinedDomainError(
                "This query is undefined in V1 real mode."
            )
        if any(entry.is_real is False for entry in (list(value) if isinstance(value, sp.MatrixBase) else [value])):
            raise RealDomainError(
                "This query produces a complex value, which is outside V1 real mode."
            )
        if not value.free_symbols and any(entry.is_real is None for entry in (list(value) if isinstance(value, sp.MatrixBase) else [value])):
            raise UnresolvedValueError(
                "SymPy could not establish a valid real value for this query."
            )
        if (
            value.free_symbols
            and not allow_symbolic
            and not _query_allows_symbolic_result(relation)
        ):
            unresolved_symbols.update(value.free_symbols)
        values.append(value)
    return values, unresolved_symbols


def _validate_candidates(candidates, equations, variables):
    valid = []
    unresolved = False
    for values in candidates:
        assignments = dict(zip(variables, values, strict=True))
        candidate_valid = True
        for equation in equations:
            residual = sp.simplify(equation.subs(assignments, simultaneous=True))
            if residual == 0 or residual.is_zero is True:
                continue
            if residual.is_zero is False:
                candidate_valid = False
                break
            unresolved = True
            candidate_valid = False
            break
        if candidate_valid:
            valid.append((values, assignments))
    return valid, unresolved


def _vector(value, operation):
    if not isinstance(value, sp.MatrixBase) or value.cols != 1:
        raise UnsupportedFeature(f"{operation} requires column vectors")
    return value


def _matrix_call(name, args):
    a = args[0]
    if name in {"grad", "jacobian", "div", "curl", "hessian"}:
        variables = list(_vector(args[1], name))
        if not all(isinstance(v, sp.Symbol) for v in variables) or len(set(variables)) != len(variables):
            raise UnsupportedFeature(f"{name} requires a list of distinct variables")
        if name in {"grad", "hessian"}:
            if isinstance(a, sp.MatrixBase):
                raise UnsupportedFeature(f"{name} requires a scalar expression")
            return sp.ImmutableMatrix([sp.diff(a, v) for v in variables]) if name == "grad" else sp.ImmutableMatrix(sp.hessian(a, variables))
        a = _vector(a, name)
        if name == "jacobian":
            return a.jacobian(variables)
        if len(a) != len(variables):
            raise UnsupportedFeature(f"{name} requires one vector component per variable")
        if name == "div":
            return sum(sp.diff(a[i], v) for i, v in enumerate(variables))
        if len(variables) != 3:
            raise UnsupportedFeature("curl requires three components and three variables")
        return sp.ImmutableMatrix([sp.diff(a[2], variables[1])-sp.diff(a[1], variables[2]), sp.diff(a[0], variables[2])-sp.diff(a[2], variables[0]), sp.diff(a[1], variables[0])-sp.diff(a[0], variables[1])])
    if not isinstance(a, sp.MatrixBase):
        raise UnsupportedFeature(f"{name} requires a vector or matrix")
    if name in {"dot", "cross", "norm", "unit"}:
        _vector(a, name)
        if name in {"dot", "cross"}:
            b = _vector(args[1], name)
            if a.shape != b.shape:
                raise UnsupportedFeature(f"{name} requires vectors of equal length")
            if name == "cross" and a.rows != 3:
                raise UnsupportedFeature("cross requires 3D vectors")
            return a.dot(b) if name == "dot" else a.cross(b)
        length = sp.sqrt(a.dot(a))
        if name == "unit" and length == 0:
            raise UnsupportedFeature("The zero vector has no unit vector")
        return length if name == "norm" else a / length
    if name == "transpose": return a.T
    if name == "rank": return sp.Integer(a.rank())
    if name == "linsolve":
        b = _vector(args[1], name)
        if a.rows != b.rows:
            raise UnsupportedFeature("linsolve requires one right-hand entry per matrix row")
        result = sp.linsolve((a, b))
        if result == sp.EmptySet:
            raise UnsupportedFeature("This linear system has no solution")
        return sp.ImmutableMatrix(next(iter(result)))
    if a.rows != a.cols:
        raise UnsupportedFeature(f"{name} requires a square matrix")
    if name == "det": return a.det()
    if name == "trace": return a.trace()
    if name == "inv":
        if a.det() == 0:
            raise UnsupportedFeature("A singular matrix has no inverse")
        return a.inv()
    raise UnsupportedFeature(f"Unsupported matrix operation: {name}")


def _has_matrix(node):
    if isinstance(node, list):
        return any(_has_matrix(item) for item in node)
    if not isinstance(node, dict):
        return False
    return node.get("kind") == "array" or node.get("name") in {"dot", "cross", "norm", "unit", "transpose", "det", "inv", "trace", "rank", "linsolve", "grad", "jacobian", "div", "curl", "hessian"} or any(_has_matrix(value) for value in node.values())


def _solve_matrix_relations(relations):
    definitions = {}
    for row in relations:
        if row["kind"] != "equation": continue
        if row["left"]["kind"] != "symbol":
            raise UnsupportedFeature("Use name = expression for matrix definitions and linsolve(A,b) for linear systems")
        name = row["left"]["name"].lower()
        if name in definitions:
            raise UnsupportedFeature(f"Multiple definitions for {name}")
        definitions[name] = row["right"]

    class Definitions(dict):
        def __init__(self, blocked=()):
            super().__init__()
            self.pending = set()
            self.blocked = set(blocked)

        def without(self, names):
            return Definitions(self.blocked | names)

        def setdefault(self, name, default=None):
            if name in self: return self[name]
            if name not in definitions or name in self.blocked: return super().setdefault(name, default)
            if name in self.pending:
                raise UnsupportedFeature(f"Circular definition involving {name}")
            self.pending.add(name)
            try:
                self[name] = build_expr(definitions[name], self)
            finally:
                self.pending.remove(name)
            return self[name]

    symbols = Definitions()
    values = {name: symbols.setdefault(name) for name in definitions}
    # Validate declarations through the same real-domain checks as queries.
    rows = [{"kind": "query", "expression": {"kind": "symbol", "name": name}} for name in definitions]
    rows += [row for row in relations if row["kind"] == "query"]
    evaluated, _ = _evaluate_queries(rows, symbols, {}, allow_symbolic=True)
    return {"status": "solved", "variables": list(values), "solutions": [{"assignments": {name: _display_value(evaluated[index]) for index, name in enumerate(values)}, "queries": [_display_value(value) for value in evaluated[len(values):]]}]}


def solve_payload(payload):
    try:
        relations = payload.get("relations", []) if isinstance(payload, dict) else []
        if not relations:
            return {"status": "error", "message": "No relations were supplied."}
        mode = payload.get("mode", "system")
        if mode not in {"system", "symbolic", "workspace"}:
            raise UnsupportedFeature(f"Unsupported solver mode: {mode}")
        allow_symbolic = mode in {"symbolic", "workspace"}

        equation_rows = [row for row in relations if row.get("kind") == "equation"]
        query_rows = [row for row in relations if row.get("kind") == "query"]
        if len(equation_rows) + len(query_rows) != len(relations):
            raise UnsupportedFeature("Relations must be equations or queries")

        if any(_has_matrix(row) for row in relations):
            return _solve_matrix_relations(relations)

        variable_names = _equation_symbol_names(relations)
        equation_count = len(equation_rows)
        if equation_count > len(variable_names):
            return {
                "status": "overdefined",
                "equationCount": equation_count,
                "variableCount": len(variable_names),
                "message": f"{equation_count} equation{'s' if equation_count != 1 else ''} exceeds {len(variable_names)} distinct unknowns.",
            }

        symbols = {name: sp.Symbol(name, real=True) for name in variable_names}
        variables = [symbols[name] for name in variable_names]
        equations = [
            build_expr(row["left"], symbols) - build_expr(row["right"], symbols)
            for row in equation_rows
        ]

        if not equations:
            query_values, free = _evaluate_queries(
                query_rows, symbols, {}, allow_symbolic=allow_symbolic
            )
            if free:
                return _underdetermined(free)
            return {
                "status": "solved",
                "variables": [],
                "solutions": [
                    {
                        "assignments": {},
                        "queries": [_display_value(value) for value in query_values],
                    }
                ],
            }

        solution_set = sp.nonlinsolve(equations, variables)
        classification = classify_solution_set(
            solution_set, variables, allow_symbolic=allow_symbolic
        )
        if classification["status"] != "solved":
            return classification

        valid, validation_unresolved = _validate_candidates(
            classification["raw_solutions"], equations, variables
        )
        if validation_unresolved:
            return {
                "status": "unresolved",
                "message": "SymPy produced candidates that could not be verified exactly.",
            }
        if not valid:
            return {"status": "no-solution", "message": "No real solution exists."}

        display_variables = [
            variable
            for variable in variables
            if not allow_symbolic
            or any(assignments[variable] != variable for _, assignments in valid)
        ]
        if mode == "workspace":
            # Only lock a variable if every solution determines its value.
            # Free parameters stay editable even when other variables are solved.
            display_variables = [
                variable for variable in display_variables
                if all(not assignments[variable].free_symbols for _, assignments in valid)
            ]
        serialized_solutions = []
        for _, assignments in valid:
            query_values, free = _evaluate_queries(
                query_rows,
                symbols,
                assignments,
                allow_symbolic=allow_symbolic,
            )
            if free:
                return _underdetermined(free)
            serialized_solutions.append(
                {
                    "assignments": {
                        str(variable): _display_value(assignments[variable])
                        for variable in display_variables
                    },
                    "queries": [_display_value(value) for value in query_values],
                }
            )

        return {
            "status": "solved",
            "variables": [str(variable) for variable in display_variables],
            "solutions": serialized_solutions,
        }
    except UndefinedDomainError as error:
        return {
            "status": "unsupported",
            "message": str(error),
            "feature": "undefined-domain",
        }
    except UnresolvedValueError as error:
        return {
            "status": "unresolved",
            "message": str(error),
        }
    except RealDomainError as error:
        return {
            "status": "unsupported",
            "message": str(error),
            "feature": "complex-domain",
        }
    except UnsupportedFeature as error:
        return {
            "status": "unsupported",
            "message": str(error),
            "feature": str(error),
        }
    except NotImplementedError as error:
        return {
            "status": "unresolved",
            "message": "SymPy does not implement this valid operation.",
            "detail": str(error),
        }
    except Exception as error:  # worker boundary: always return a serializable state
        return {"status": "error", "message": f"Solver error: {error}"}

import { hasProbability } from '@/registry/calculator/lib/probability'
import { prepareProbabilityPlot } from '@/registry/calculator/lib/probability-plot'
import { hasMatrixValues, type ExpressionAst } from '@/registry/calculator/lib/dsl/ast'
import { collectFreeSymbols } from '@/registry/calculator/lib/dsl/analyze'
import type { Relation } from '@/registry/calculator/lib/model'

export const PLOT_DOMAIN: [number, number] = [-10, 10]
export type PlotViewport = { x: [number, number]; y: [number, number] }
export const DEFAULT_VIEWPORT: PlotViewport = { x: [-10, 10], y: [-10, 10] }
type Evaluate = (values: Record<string, number>) => number
export type PlotPoint = { x: number; y: number | null; shaded?: number }
export type PlotCurve = { id: string; label: string; fn?: (x: number) => number; data?: PlotPoint[]; discrete?: boolean; shaded?: boolean }

const functions: Record<string, (value: number) => number> = {
  sqrt: Math.sqrt, abs: Math.abs, exp: Math.exp, ln: Math.log, log: Math.log,
  log10: Math.log10, sin: Math.sin, cos: Math.cos, tan: Math.tan,
  asin: Math.asin, acos: Math.acos, atan: Math.atan,
  sinh: Math.sinh, cosh: Math.cosh, tanh: Math.tanh,
  simplify: (value) => value, expand: (value) => value, factor: (value) => value,
}

function compile(node: ExpressionAst): Evaluate {
  switch (node.kind) {
    case 'array': throw new Error('Plot a two-component vector or parametric curve.')
    case 'comparison': throw new Error('Use P(event) to plot a probability event.')
    case 'number': return () => Number(node.value)
    case 'constant': return () => node.name === 'pi' ? Math.PI : Math.E
    case 'symbol': return (values) => values[node.name.toLowerCase()] ?? NaN
    case 'unary': {
      const operand = compile(node.operand)
      return (values) => (node.operator === '-' ? -1 : 1) * operand(values)
    }
    case 'binary': {
      const left = compile(node.left)
      const right = compile(node.right)
      return (values) => {
        const a = left(values), b = right(values)
        switch (node.operator) {
          case '+': return a + b
          case '-': return a - b
          case '*': return a * b
          case '/': return a / b
          case '^': return a ** b
        }
      }
    }
    case 'factorial': {
      const operand = compile(node.operand)
      return (values) => {
        const n = operand(values)
        if (!Number.isInteger(n) || n < 0 || n > 170) return NaN
        let result = 1
        for (let i = 2; i <= n; i++) result *= i
        return result
      }
    }
    case 'call': {
      const fn = functions[node.name]
      if (!fn) throw new Error(`Plotting ${node.name} is not supported. Use its evaluated expression instead.`)
      const argument = compile(node.args[0]!)
      return (values) => fn(argument(values))
    }
  }
}

// Trace zero contours in the visible viewing window. Triangles avoid ambiguous
// four-edge crossings; null separators keep independent segments disconnected.
export function sampleEquation(fn: (x: number, y: number) => number, viewport = DEFAULT_VIEWPORT): PlotPoint[] {
  const steps = 100
  const { x: [left, right], y: [bottom, top] } = viewport
  const grid = Array.from({ length: steps + 1 }, (_, row) =>
    Array.from({ length: steps + 1 }, (_, col) => {
      const x = left + col * (right - left) / steps
      const y = bottom + row * (top - bottom) / steps
      return { x, y, value: fn(x, y) }
    }),
  )
  type Vertex = typeof grid[number][number]
  const data: PlotPoint[] = []
  function triangle(vertices: Vertex[]) {
    const crossings: PlotPoint[] = []
    for (let i = 0; i < 3; i++) {
      const a = vertices[i]!, b = vertices[(i + 1) % 3]!
      if (!Number.isFinite(a.value) || !Number.isFinite(b.value)) continue
      if ((a.value < 0) === (b.value < 0)) continue
      let left = a, right = b
      // Refine and reject sign changes caused by poles rather than roots.
      for (let j = 0; j < 24; j++) {
        const x = (left.x + right.x) / 2, y = (left.y + right.y) / 2
        const middle = { x, y, value: fn(x, y) }
        if ((middle.value < 0) === (left.value < 0)) left = middle
        else right = middle
      }
      const point = Math.abs(left.value) < Math.abs(right.value) ? left : right
      if (Math.abs(point.value) <= 1e-6 * Math.max(1, Math.abs(a.value), Math.abs(b.value))) {
        crossings.push({ x: point.x, y: point.y })
      }
    }
    if (crossings.length === 2) data.push(...crossings, { x: crossings[1]!.x, y: null })
  }
  for (let row = 0; row < steps; row++) {
    for (let col = 0; col < steps; col++) {
      const a = grid[row]![col]!, b = grid[row]![col + 1]!
      const c = grid[row + 1]![col + 1]!, d = grid[row + 1]![col]!
      triangle([a, b, c])
      triangle([a, c, d])
    }
  }
  return data
}

export function preparePlot(relations: readonly Relation[], viewport?: PlotViewport): { xLabel: string; yLabel: string; curves: PlotCurve[]; viewport?: PlotViewport } {
  if (hasProbability(relations.filter(row => row.enabled).map(row => row.ast))) return prepareProbabilityPlot(relations, viewport)
  if (hasMatrixValues(relations.filter(row => row.enabled).map(row => row.ast))) return prepareVectorPlot(relations, viewport ?? DEFAULT_VIEWPORT)
  viewport ??= DEFAULT_VIEWPORT
  const selected = relations.filter((relation) => relation.enabled)
  const symbols = new Set<string>()
  for (const { ast } of selected) {
    const expressions = ast.kind === 'equation' ? [ast.left, ast.right] : [ast.expression]
    for (const expression of expressions) {
      for (const name of collectFreeSymbols(expression)) symbols.add(name)
    }
  }
  if (symbols.size > 2) {
    throw new Error(`Cannot plot more than 2 variables. The ticked relations contain ${symbols.size}: ${[...symbols].sort().join(', ')}. Untick relations to use at most 2 variables.`)
  }
  const names = [...symbols].sort()
  const xLabel = symbols.has('x') ? 'x' : names.find((name) => name !== 'y') ?? 'x'
  const yLabel = names.find((name) => name !== xLabel) ?? 'y'
  const curves = selected.map((relation) => {
    const { ast } = relation
    if (ast.kind === 'query') {
      if (collectFreeSymbols(ast.expression).size > 1) {
        throw new Error(`Write an equation for "${relation.source}" to plot a relation between two variables.`)
      }
      const evaluate = compile(ast.expression)
      const variable = [...collectFreeSymbols(ast.expression)][0] ?? xLabel
      return { id: relation.id, label: relation.source, fn: (x: number) => evaluate({ [variable]: x }) }
    }
    const left = compile(ast.left), right = compile(ast.right)
    const data = sampleEquation((x, y) => {
      const values = { [xLabel]: x, [yLabel]: y }
      return left(values) - right(values)
    }, viewport)
    return { id: relation.id, label: relation.source, data }
  })
  return { xLabel, yLabel, curves }
}


function prepareVectorPlot(relations: readonly Relation[], viewport: PlotViewport) {
  const selected = relations.filter(row => row.enabled)
  const definitions = new Map<string, ExpressionAst>()
  for (const { ast } of selected) if (ast.kind === 'equation' && ast.left.kind === 'symbol') {
    const name = ast.left.name.toLowerCase()
    if (definitions.has(name)) throw new Error(`Multiple definitions for ${name}`)
    definitions.set(name, ast.right)
  }
  function expand(node: ExpressionAst, visiting = new Set<string>()): ExpressionAst {
    if (node.kind === 'symbol' && definitions.has(node.name.toLowerCase())) {
      const name = node.name.toLowerCase()
      if (visiting.has(name)) throw new Error(`Circular definition involving ${name}`)
      return expand(definitions.get(name)!, new Set([...visiting, name]))
    }
    if (node.kind === 'array') return { ...node, items: node.items.map(item => expand(item, visiting)) }
    if (node.kind === 'binary') {
      const left = expand(node.left, visiting), right = expand(node.right, visiting)
      if (left.kind === 'array' || right.kind === 'array') {
        if ((node.operator === '+' || node.operator === '-') && left.kind === 'array' && right.kind === 'array' && left.items.length === right.items.length) {
          return { kind: 'array', items: left.items.map((item, i) => expand({ ...node, left: item, right: right.items[i]! }, visiting)) }
        }
        if (node.operator === '*' && (left.kind === 'array') !== (right.kind === 'array')) {
          const items = left.kind === 'array' ? left.items : right.kind === 'array' ? right.items : []
          return { kind: 'array', items: items.map(item => expand({ ...node, left: left.kind === 'array' ? item : left, right: right.kind === 'array' ? item : right }, visiting)) }
        }
        throw new Error('For this operation, plot its evaluated two-component vector instead.')
      }
      return { ...node, left, right }
    }
    if (node.kind === 'unary') {
      const operand = expand(node.operand, visiting)
      return operand.kind === 'array' ? { kind: 'array', items: operand.items.map(item => ({ ...node, operand: item })) } : { ...node, operand }
    }
    if (node.kind === 'call') return { ...node, args: node.args.map(arg => expand(arg, visiting)) }
    return node
  }
  const curves: PlotCurve[] = []
  for (const row of selected) {
    if (row.ast.kind === 'equation' && row.ast.left.kind !== 'symbol') throw new Error('Select vector definitions or two-component expressions to plot together.')
    const node = expand(row.ast.kind === 'query' ? row.ast.expression : row.ast.right)
    if (node.kind !== 'array') {
      if (row.ast.kind === 'equation' && collectFreeSymbols(node).size === 0) continue
      throw new Error('Select two-component vectors or parametric expressions to plot.')
    }
    if (node.items.length !== 2 || node.items.some(item => item.kind === 'array')) throw new Error('Only 2D vectors and two-component parametric curves can be plotted.')
    const names = [...collectFreeSymbols(node)]
    if (names.length > 1) throw new Error('A parametric curve requires exactly one free parameter.')
    const fx = compile(node.items[0]!), fy = compile(node.items[1]!)
    let data: PlotPoint[]
    if (names.length) {
      data = Array.from({ length: 801 }, (_, index) => {
        const values = { [names[0]!]: -10 + index / 800 * 20 }
        const x = fx(values), y = fy(values)
        return { x: Number.isFinite(x) ? x : 0, y: Number.isFinite(x) && Number.isFinite(y) ? y : null }
      })
    } else {
      const x = fx({}), y = fy({})
      if (!Number.isFinite(x) || !Number.isFinite(y)) throw new Error('Vector coordinates must be finite real numbers.')
      const dx = x / (viewport.x[1] - viewport.x[0]), dy = y / (viewport.y[1] - viewport.y[0])
      const length = Math.hypot(dx, dy), size = Math.min(0.025, length / 3)
      const ux = length ? dx / length * size : 0, uy = length ? dy / length * size : 0
      data = [{ x: 0, y: 0 }, { x, y }, { x: x - (ux + uy / 2) * (viewport.x[1] - viewport.x[0]), y: y - (uy - ux / 2) * (viewport.y[1] - viewport.y[0]) }, { x, y }, { x: x - (ux - uy / 2) * (viewport.x[1] - viewport.x[0]), y: y - (uy + ux / 2) * (viewport.y[1] - viewport.y[0]) }]
    }
    curves.push({ id: row.id, label: names.length ? `${row.source} (${names[0]}: −10…10)` : row.source, data })
  }
  return { xLabel: 'x', yLabel: 'y', curves }
}

'use client'

import { useMemo, useState } from 'react'
import { Area, CartesianGrid, ComposedChart, getNiceTickValues, Line, XAxis, YAxis } from 'recharts'
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert'
import { ChartContainer, ChartLegend, ChartLegendContent } from '@/components/ui/chart'
import type { Relation } from '@/registry/calculator/lib/model'
import { DEFAULT_VIEWPORT, preparePlot, type PlotPoint } from '@/registry/calculator/lib/plot'

import { Button } from '@/components/ui/button'
import { PlotInteraction } from '@/registry/calculator/ui/plot-interaction'

function formatTick(value: number) {
  const magnitude = Math.abs(value)
  const rounded = Number(value.toPrecision(10))
  return magnitude !== 0 && (magnitude >= 100000 || magnitude < 0.0001)
    ? rounded.toExponential()
    : String(rounded)
}

export function RelationPlot({ relations }: { relations: readonly Relation[] }) {
  return <PlotCanvas key={relations.filter(row => row.enabled).map(row => `${row.id}:${row.source}`).join('|')} relations={relations} />
}

function PlotCanvas({ relations }: { relations: readonly Relation[] }) {
  const initialView = useMemo(() => {
    try { return preparePlot(relations).viewport ?? DEFAULT_VIEWPORT } catch { return DEFAULT_VIEWPORT }
  }, [relations])
  const [view, setView] = useState(initialView)
  const result = useMemo(() => {
    try {
      const plot = preparePlot(relations, view)
      return { plot: { ...plot, curves: plot.curves.map((curve) => ({
        ...curve,
        data: curve.fn ? Array.from({ length: 400 }, (_, index): PlotPoint => {
          const x = view.x[0] + index / 399 * (view.x[1] - view.x[0])
          const y = curve.fn!(x)
          return { x, y: Number.isFinite(y) ? y : null }
        }) : curve.data,
      })) } }
    } catch (error) {
      return { error: error instanceof Error ? error.message : 'Unable to plot the selected relations.' }
    }
  }, [relations, view])

  if (!result.plot) {
    return <Alert variant="destructive" role="alert"><AlertTitle>Cannot plot</AlertTitle><AlertDescription>{result.error}</AlertDescription></Alert>
  }
  const { curves, xLabel, yLabel } = result.plot
  if (curves.length === 0) {
    return <Alert><AlertTitle>No relations selected</AlertTitle><AlertDescription>Tick a saved equation or expression to plot it.</AlertDescription></Alert>
  }
  const config = Object.fromEntries(curves.map((curve, index) => [curve.id, {
    label: curve.label, color: `var(--chart-${index % 5 + 1})`,
  }]))
  const xTicks = getNiceTickValues(view.x, 5).filter((tick) => tick >= view.x[0] && tick <= view.x[1])
  const yTicks = getNiceTickValues(view.y, 5).filter((tick) => tick >= view.y[0] && tick <= view.y[1])
  return (
    <div className="grid min-w-0 max-w-full gap-2">
      <ChartContainer className="aspect-auto min-w-0 max-w-full overflow-hidden" config={config} initialDimension={{ width: 320, height: 360 }} style={{ width: '100%', height: 360 }}>
        <ComposedChart accessibilityLayer aria-label="Selected relations plot" margin={{ top: 12, right: 16, bottom: 20, left: 8 }}>
          <CartesianGrid />
          <XAxis dataKey="x" type="number" domain={view.x} ticks={xTicks} tickFormatter={formatTick} minTickGap={24} allowDataOverflow label={{ value: xLabel, position: 'insideBottom', offset: -12 }} />
          <YAxis type="number" domain={view.y} ticks={yTicks} tickFormatter={formatTick} width={80} minTickGap={12} allowDataOverflow label={{ value: yLabel, angle: -90, position: 'insideLeft' }} />
          {curves.filter(curve => curve.shaded && !curve.discrete).map(curve => (
            <Area key={`${curve.id}-area`} data={curve.data} dataKey="shaded" type="linear" fill={config[curve.id]!.color} fillOpacity={0.25} stroke="none" legendType="none" isAnimationActive={false} />
          ))}
          {curves.map((curve) => curve.discrete ? (
            <Line key={curve.id} name={curve.id} data={curve.data?.flatMap(p => [{ x: p.x, y: 0 }, p, { x: p.x, y: null }])} dataKey="y" stroke={config[curve.id]!.color} strokeOpacity={curve.shaded ? 0.25 : 0.8} strokeWidth={6} dot={false} activeDot={false} isAnimationActive={false} />
          ) : (
            <Line key={curve.id} name={curve.id} data={curve.data} dataKey="y" type="linear" dot={false} activeDot={false} connectNulls={false} isAnimationActive={false} stroke={config[curve.id]!.color} />
          ))}
          {curves.filter(curve => curve.shaded && curve.discrete).map(curve => (
            <Line key={`${curve.id}-selected`} data={curve.data?.flatMap(p => [{ x: p.x, y: 0 }, { x: p.x, y: p.shaded ?? 0 }, { x: p.x, y: null }])} dataKey="y" stroke={config[curve.id]!.color} strokeWidth={6} dot={false} activeDot={false} legendType="none" isAnimationActive={false} />
          ))}
          <PlotInteraction view={view} onChange={setView} />
          <ChartLegend content={<ChartLegendContent nameKey="name" className="flex-wrap gap-x-3 gap-y-1 [&>div]:min-w-0 [&>div]:max-w-full [&_span]:truncate" />} />
        </ComposedChart>
      </ChartContainer>
      <div className="flex flex-wrap items-center justify-between gap-2">
        <p className="text-sm text-muted-foreground">Drag to pan. Scroll to zoom. Plots are approximate.</p>
        <Button variant="outline" size="sm" onClick={() => setView(initialView)}>Reset view</Button>
      </div>
    </div>
  )
}

import type { PlotViewport } from '@/registry/calculator/lib/plot'

export function panViewport(view: PlotViewport, dx: number, dy: number): PlotViewport {
  const x = dx * (view.x[1] - view.x[0])
  const y = dy * (view.y[1] - view.y[0])
  return { x: [view.x[0] - x, view.x[1] - x], y: [view.y[0] + y, view.y[1] + y] }
}

export function zoomViewport(view: PlotViewport, x: number, y: number, factor: number): PlotViewport {
  const zoom = (domain: [number, number], anchor: number): [number, number] => {
    const span = domain[1] - domain[0]
    const nextSpan = Math.min(1e8, Math.max(1e-6, span * factor))
    const low = domain[0] + anchor * (span - nextSpan)
    return [low, low + nextSpan]
  }
  return { x: zoom(view.x, x), y: zoom(view.y, 1 - y) }
}

'use client'

import { useEffect, useRef } from 'react'
import { usePlotArea } from 'recharts'
import type { PlotViewport } from '@/registry/calculator/lib/plot'
import { panViewport, zoomViewport } from '@/registry/calculator/lib/plot-interaction'

export function PlotInteraction({ view, onChange }: {
  view: PlotViewport
  onChange: (view: PlotViewport) => void
}) {
  const area = usePlotArea()
  const surface = useRef<SVGRectElement>(null)
  const drag = useRef<{ id: number; x: number; y: number; view: PlotViewport } | null>(null)
  useEffect(() => {
    const element = surface.current
    if (!element || !area) return
    const wheel = (event: WheelEvent) => {
      event.preventDefault()
      const rect = element.getBoundingClientRect()
      const delta = event.deltaY * (event.deltaMode === 1 ? 16 : event.deltaMode === 2 ? rect.height : 1)
      onChange(zoomViewport(view, (event.clientX - rect.left) / rect.width,
        (event.clientY - rect.top) / rect.height, Math.exp(Math.max(-1, Math.min(1, delta * 0.002)))))
    }
    element.addEventListener('wheel', wheel, { passive: false })
    return () => element.removeEventListener('wheel', wheel)
  }, [area, view, onChange])
  if (!area) return null
  return (
    <g>
      <rect ref={surface} x={area.x} y={area.y} width={area.width} height={area.height}
        fill="transparent" style={{ touchAction: 'none', cursor: drag.current ? 'grabbing' : 'grab' }}
        onPointerDown={(event) => {
          if (event.button !== 0 || drag.current) return
          event.currentTarget.setPointerCapture(event.pointerId)
          drag.current = { id: event.pointerId, x: event.clientX, y: event.clientY, view }
        }}
        onPointerMove={(event) => {
          const rect = event.currentTarget.getBoundingClientRect()
          const start = drag.current
          if (start && start.id === event.pointerId) {
            onChange(panViewport(start.view, (event.clientX - start.x) / rect.width, (event.clientY - start.y) / rect.height))
          }
        }}
        onPointerUp={(event) => {
          if (drag.current?.id !== event.pointerId) return
          drag.current = null
          event.currentTarget.releasePointerCapture(event.pointerId)
        }}
        onLostPointerCapture={() => { drag.current = null }}
        onPointerCancel={() => { drag.current = null }}
      />
    </g>
  )
}

// jStat does not publish TypeScript declarations.
// @ts-expect-error Untyped upstream module; the used API is described below.
import jstat from 'jstat'

type Family = { pdf(x: number, ...args: number[]): number; cdf(x: number, ...args: number[]): number; inv(p: number, ...args: number[]): number; mean(...args: number[]): number; variance(...args: number[]): number }
const stats = jstat.jStat as Record<string, Family> & { gammaln(x: number): number; lowRegGamma(a: number, x: number): number; ibeta(x: number, a: number, b: number): number; erfc(x: number): number }

export const DISTRIBUTIONS = {
  Norm: ['mean', 'variance'], N: ['mean', 'variance'], Pois: ['rate'],
  Bin: ['trials', 'probability'], Bern: ['probability'], Unif: ['lower', 'upper'],
  Exp: ['rate'], Weib: ['shape', 'scale'], Gamma: ['shape', 'scale'],
  Beta: ['alpha', 'beta'], T: ['degrees'], Chi2: ['degrees'], F: ['degrees1', 'degrees2'],
} as const
export type DistributionName = keyof typeof DISTRIBUTIONS
export function isDistribution(name: string): name is DistributionName { return Object.hasOwn(DISTRIBUTIONS, name) }
export type Distribution = {
  discrete: boolean
  support: [number, number]
  pdf(x: number): number
  cdf(x: number): number
  sf(x: number): number
  quantile(p: number): number
  mean(): number
  variance(): number
}

export function distribution(name: DistributionName, args: number[]): Distribution {
  if (args.length !== DISTRIBUTIONS[name].length || args.some(x => !Number.isFinite(x))) throw new Error(`${name} requires finite numeric parameters.`)
  const [a, b] = args as [number, number]
  const positive = (x: number, label: string) => { if (!(x > 0)) throw new Error(`${name}: ${label} must be greater than zero.`) }
  const probability = (x: number) => { if (x < 0 || x > 1) throw new Error(`${name}: probability must be between 0 and 1.`) }
  let family: Family
  let parameters = args
  let support: [number, number] = [0, Infinity]
  let discrete = false
  switch (name) {
    case 'Norm': case 'N': positive(b, 'variance'); family = stats.normal; parameters = [a, Math.sqrt(b)]; support = [-Infinity, Infinity]; break
    case 'Pois': if (a < 0) throw new Error('Pois: rate must be nonnegative.'); family = stats.poisson; discrete = true; if (a === 0) support = [0, 0]; break
    case 'Bin': if (!Number.isSafeInteger(a) || a < 0) throw new Error('Bin: trials must be a nonnegative integer.'); probability(b); family = stats.binomial; discrete = true; support = b === 0 ? [0, 0] : b === 1 ? [a, a] : [0, a]; break
    case 'Bern': probability(a); family = stats.binomial; parameters = [1, a]; discrete = true; support = a === 0 ? [0, 0] : a === 1 ? [1, 1] : [0, 1]; break
    case 'Unif': if (!(b > a)) throw new Error('Unif: upper bound must exceed lower bound.'); family = stats.uniform; support = [a, b]; break
    case 'Exp': positive(a, 'rate'); family = stats.exponential; break
    case 'Weib': positive(a, 'shape'); positive(b, 'scale'); family = stats.weibull; parameters = [b, a]; break
    case 'Gamma': positive(a, 'shape'); positive(b, 'scale'); family = stats.gamma; break
    case 'Beta': positive(a, 'alpha'); positive(b, 'beta'); family = stats.beta; support = [0, 1]; break
    case 'T': positive(a, 'degrees of freedom'); family = stats.studentt; support = [-Infinity, Infinity]; break
    case 'Chi2': positive(a, 'degrees of freedom'); family = stats.chisquare; break
    case 'F': positive(a, 'numerator degrees of freedom'); positive(b, 'denominator degrees of freedom'); family = stats.centralF; break
  }
  const clamp = (x: number) => {
    if (!Number.isFinite(x)) throw new Error(`Could not evaluate ${name} accurately for these parameters.`)
    return Math.max(0, Math.min(1, x))
  }
  // Continued fraction for the Normal survival function avoids 1 - erf
  // cancellation in jStat's extreme tails (Laplace's Mills-ratio fraction).
  const normalTail = (z: number): number => {
    if (z === 0) return 0.5
    if (z < 0) return 1 - normalTail(-z)
    if (z < 5) return stats.erfc(z / Math.SQRT2) / 2
    let fraction = 0
    for (let i = 100; i >= 1; i--) fraction = i / (z + fraction)
    return Math.exp(-z * z / 2) / Math.sqrt(2 * Math.PI) / (z + fraction)
  }
  const cdf = (x: number): number => {
    if (x < support[0]) return 0
    if (x >= support[1]) return 1
    if (x === -Infinity) return 0
    if (discrete) x = Math.floor(x)
    // Use the incomplete beta rather than jStat's rounded binomial CDF.
    if (name === 'Bin' || name === 'Bern') return clamp(stats.ibeta(1 - parameters[1], parameters[0] - x, x + 1))
    if (name === 'Pois') return clamp(1 - stats.lowRegGamma(x + 1, a))
    if (name === 'Norm' || name === 'N') return normalTail((a - x) / Math.sqrt(b))
    return clamp(family.cdf(x, ...parameters))
  }
  const sf = (x: number): number => {
    if (x < support[0] || x === -Infinity) return 1
    if (x >= support[1]) return 0
    if (name === 'Norm' || name === 'N') return normalTail((x - a) / Math.sqrt(b))
    if (name === 'Exp') return Math.exp(-a * x)
    if (name === 'Weib') return Math.exp(-Math.pow(x / b, a))
    if (name === 'Pois') return clamp(stats.lowRegGamma(Math.floor(x) + 1, a))
    if (name === 'Bin' || name === 'Bern') return clamp(stats.ibeta(parameters[1], Math.floor(x) + 1, parameters[0] - Math.floor(x)))
    return clamp(1 - cdf(x))
  }
  const quantile = (p: number): number => {
    if (!Number.isFinite(p) || p < 0 || p > 1) throw new Error('quantile: probability must be between 0 and 1.')
    if (p === 0) return support[0]
    if (p === 1) return support[1]
    if (!discrete) return family.inv(p, ...parameters)
    let low = support[0], high = Number.isFinite(support[1]) ? support[1] : Math.max(1, Math.ceil(a))
    while (cdf(high) < p && high < Number.MAX_SAFE_INTEGER / 2) high *= 2
    if (cdf(high) < p) throw new Error('Quantile exceeds the supported numeric range.')
    while (low < high) {
      const middle = low + Math.floor((high - low) / 2)
      if (cdf(middle) >= p) high = middle
      else low = middle + 1
    }
    return low
  }
  return {
    discrete, support, cdf, sf, quantile,
    pdf(x) {
      if (x < support[0] || x > support[1] || (discrete && !Number.isInteger(x))) return 0
      if (support[0] === support[1]) return x === support[0] ? 1 : 0
      if (name === 'Bin' || name === 'Bern') {
        const [n, p] = parameters
        return Math.exp(stats.gammaln(n + 1) - stats.gammaln(x + 1) - stats.gammaln(n - x + 1) + x * Math.log(p) + (n - x) * Math.log1p(-p))
      }
      if (name === 'Pois') return Math.exp(x * Math.log(a) - a - stats.gammaln(x + 1))
      return family.pdf(x, ...parameters)
    },
    mean() {
      if (name === 'Bin' || name === 'Bern') return parameters[0] * parameters[1]
      if (name === 'Pois') return a
      return family.mean(...parameters)
    },
    variance() {
      if (name === 'Bin' || name === 'Bern') return parameters[0] * parameters[1] * (1 - parameters[1])
      if (name === 'Pois') return a
      return family.variance(...parameters)
    },
  }
}

import type { ComparisonOperator, ExpressionAst, RelationAst } from '@/registry/calculator/lib/dsl/ast'
import { toMathMl } from '@/registry/calculator/lib/dsl/mathml'
import { toLatex } from '@/registry/calculator/lib/dsl/latex'
import { distribution, isDistribution, type Distribution } from '@/registry/calculator/lib/distributions'
import type { DisplayValue, SolverResult } from '@/registry/calculator/lib/solver/protocol'

type RandomValue = { distribution: Distribution; identity: object; scale: number; shift: number }
type Value = number | RandomValue
const probabilityCalls = new Set(['P', 'E', 'Var', 'quantile'])
export function containsProbability(node: ExpressionAst): boolean {
  switch (node.kind) {
    case 'array': return node.items.some(containsProbability)
    case 'call': return isDistribution(node.name) || probabilityCalls.has(node.name) || node.args.some(containsProbability)
    case 'binary': return containsProbability(node.left) || containsProbability(node.right)
    case 'unary': case 'factorial': return containsProbability(node.operand)
    case 'comparison': return node.operands.some(containsProbability)
    default: return false
  }
}
export function hasProbability(relations: readonly RelationAst[]): boolean {
  return relations.some(row => row.kind === 'query' ? containsProbability(row.expression) : containsProbability(row.left) || containsProbability(row.right))
}
function numeric(value: Value): number {
  if (typeof value !== 'number') throw new Error('Use P, E, Var or quantile to obtain a number from a random variable.')
  if (!Number.isFinite(value)) throw new Error('This probability calculation requires finite numeric values.')
  return value
}
function random(value: Value): RandomValue {
  if (typeof value === 'number') throw new Error('Expected a random variable or distribution.')
  return value
}
function affine(value: RandomValue, scale: number, shift: number): Value {
  const result = { ...value, scale: value.scale * scale, shift: value.shift * scale + shift }
  return result.scale === 0 ? result.shift : result
}
function subtract(left: Value, right: Value): Value {
  if (typeof left === 'number') return typeof right === 'number' ? left - right : affine(right, -1, left)
  if (typeof right === 'number') return affine(left, 1, -right)
  if (left.identity !== right.identity) throw new Error('Combining different random variables requires a dependence model; this version supports one random variable per event.')
  const scale = left.scale - right.scale, shift = left.shift - right.shift
  return scale === 0 ? shift : { ...left, scale, shift }
}
const compare = (a: number, op: ComparisonOperator, b: number) => {
  switch (op) { case '<': return a < b; case '<=': return a <= b; case '>': return a > b; case '>=': return a >= b; case '=': return a === b; case '!=': return a !== b }
}
export type ProbabilityEvent = { random: RandomValue | null; probability: number; includes(x: number): boolean; boundaries: number[] }

export function probabilityContext(relations: readonly RelationAst[]) {
  const definitions = new Map<string, ExpressionAst[]>()
  for (const row of relations) if (row.kind === 'equation' && row.left.kind === 'symbol') {
    const name = row.left.name.toLowerCase()
    definitions.set(name, [...definitions.get(name) ?? [], row.right])
  }
  const cache = new Map<string, Value>(), resolving = new Set<string>()
  function resolve(name: string): Value {
    name = name.toLowerCase()
    if (cache.has(name)) return cache.get(name)!
    const rows = definitions.get(name)
    if (!rows) throw new Error(`Define ${name} before using it in a probability calculation.`)
    if (rows.length !== 1) throw new Error(`Probability calculations require one definition for ${name}.`)
    if (resolving.has(name)) throw new Error(`Circular definition involving ${name}.`)
    resolving.add(name)
    try { const value = evaluate(rows[0]); cache.set(name, value); return value } finally { resolving.delete(name) }
  }
  function evaluate(node: ExpressionAst): Value {
    switch (node.kind) {
      case 'array': throw new Error('Use scalar values in probability operations.')
      case 'number': return Number(node.value)
      case 'constant': return node.name === 'pi' ? Math.PI : Math.E
      case 'symbol': return resolve(node.name)
      case 'comparison': throw new Error('Comparisons belong inside P(event).')
      case 'unary': { const value = evaluate(node.operand); return node.operator === '+' ? value : typeof value === 'number' ? -value : affine(value, -1, 0) }
      case 'factorial': {
        const n = numeric(evaluate(node.operand))
        if (!Number.isInteger(n) || n < 0 || n > 170) throw new Error('Factorial requires an integer from 0 to 170.')
        let value = 1; for (let i = 2; i <= n; i++) value *= i
        return value
      }
      case 'binary': {
        const left = evaluate(node.left), right = evaluate(node.right)
        if (node.operator === '-') return subtract(left, right)
        if (node.operator === '+') return subtract(left, typeof right === 'number' ? -right : affine(right, -1, 0))
        if (node.operator === '*' && typeof left !== 'number' && typeof right === 'number') return affine(left, right, 0)
        if (node.operator === '*' && typeof right !== 'number' && typeof left === 'number') return affine(right, left, 0)
        if (node.operator === '/' && typeof left !== 'number' && typeof right === 'number' && right !== 0) return affine(left, 1 / right, 0)
        const a = numeric(left), b = numeric(right)
        return node.operator === '*' ? a * b : node.operator === '/' ? a / b : a ** b
      }
      case 'call': {
        if (isDistribution(node.name)) return { distribution: distribution(node.name, node.args.map(arg => numeric(evaluate(arg)))), identity: node, scale: 1, shift: 0 }
        if (node.name === 'P') return event(node.args[0]).probability
        if (node.name === 'E' || node.name === 'Var' || node.name === 'quantile') {
          const value = evaluate(node.args[0])
          if (typeof value === 'number') {
            if (node.name === 'quantile') { const p = numeric(evaluate(node.args[1])); if (p < 0 || p > 1) throw new Error('quantile: probability must be between 0 and 1.') }
            return node.name === 'Var' ? 0 : value
          }
          const { distribution: d, scale, shift } = value
          if (node.name === 'E') return scale * d.mean() + shift
          if (node.name === 'Var') return scale ** 2 * d.variance()
          const p = numeric(evaluate(node.args[1]))
          if (p < 0 || p > 1) throw new Error('quantile: probability must be between 0 and 1.')
          if (scale < 0 && d.discrete) throw new Error('Quantiles of decreasing discrete transformations are not supported yet.')
          return scale * d.quantile(scale > 0 ? p : 1 - p) + shift
        }
        const functions: Record<string, (x: number) => number> = { sqrt: Math.sqrt, abs: Math.abs, exp: Math.exp, ln: Math.log, log: Math.log, log10: Math.log10, sin: Math.sin, cos: Math.cos, tan: Math.tan, asin: Math.asin, acos: Math.acos, atan: Math.atan, sinh: Math.sinh, cosh: Math.cosh, tanh: Math.tanh }
        const fn = functions[node.name]
        if (!fn) throw new Error(`Evaluate ${node.name} separately before using it as a distribution parameter.`)
        return fn(numeric(evaluate(node.args[0])))
      }
    }
  }
  function event(node: ExpressionAst): ProbabilityEvent {
    if (node.kind !== 'comparison') throw new Error('P expects an event, for example P(X < 3) or P(1 <= X <= 4).')
    const values = node.operands.map(evaluate)
    const differences = node.operators.map((op, index) => ({ op, value: subtract(values[index], values[index + 1]) }))
    const variables = differences.flatMap(({ value }) => typeof value === 'number' ? [] : [value])
    const base = variables.length ? values.find((value): value is RandomValue => typeof value !== 'number') ?? null : null
    if (variables.some(value => value.identity !== base?.identity)) throw new Error('An event may involve only one random variable; independence is not assumed.')
    const includes = (x: number) => differences.every(({ op, value }) => compare(typeof value === 'number' ? value : value.scale * x + value.shift, op, 0))
    if (!base) return { random: null, probability: includes(0) ? 1 : 0, includes, boundaries: [] }
    let lower = -Infinity, upper = Infinity, lowerClosed = false, upperClosed = false
    const excluded: number[] = []
    for (const { op: original, value } of differences) {
      if (typeof value === 'number') { if (!compare(value, original, 0)) return { random: base, probability: 0, includes, boundaries: [] }; continue }
      const bound = -value.shift / value.scale
      const op = value.scale > 0 ? original : ({ '<': '>', '<=': '>=', '>': '<', '>=': '<=', '=': '=', '!=': '!=' } as const)[original]
      if (op === '!=') { excluded.push(bound); continue }
      if (op === '>' || op === '>=' || op === '=') {
        const closed = op !== '>'
        if (bound > lower) { lower = bound; lowerClosed = closed } else if (bound === lower) lowerClosed &&= closed
      }
      if (op === '<' || op === '<=' || op === '=') {
        const closed = op !== '<'
        if (bound < upper) { upper = bound; upperClosed = closed } else if (bound === upper) upperClosed &&= closed
      }
    }
    const d = base.distribution
    let result = 0
    if (lower < upper || (lower === upper && lowerClosed && upperClosed)) {
      const lo = d.discrete ? lowerClosed ? Math.ceil(lower) - 1 : Math.floor(lower) : lower
      const hi = d.discrete ? upperClosed ? Math.floor(upper) : Math.ceil(upper) - 1 : upper
      if (hi >= lo) {
        result = d.cdf(lo) > 0.5 ? d.sf(lo) - d.sf(hi) : d.cdf(hi) - d.cdf(lo)
        if (d.discrete) for (const x of new Set(excluded)) if (x >= lower && x <= upper && (x !== lower || lowerClosed) && (x !== upper || upperClosed)) result -= d.pdf(x)
      }
    }
    return { random: base, probability: Math.max(0, Math.min(1, result)), includes, boundaries: [lower, upper, ...excluded].filter(Number.isFinite) }
  }
  function isRandomDefinition(row: RelationAst): boolean {
    if (row.kind !== 'equation' || row.left.kind !== 'symbol') return false
    // Follow aliases without evaluating unrelated algebraic equations.
    function refers(node: ExpressionAst, visited = new Set<string>()): boolean {
      if (containsProbability(node)) return true
      if (node.kind === 'symbol') {
        const name = node.name.toLowerCase()
        if (visited.has(name)) return false
        const next = new Set(visited).add(name)
        return (definitions.get(name) ?? []).some(value => refers(value, next))
      }
      if (node.kind === 'binary') return refers(node.left, visited) || refers(node.right, visited)
      if (node.kind === 'unary') return refers(node.operand, visited)
      return false
    }
    return refers(row.right) && typeof resolve(row.left.name) !== 'number'
  }
  return { evaluate, event, isRandomDefinition, random }
}

export function probabilityDisplay(value: number): DisplayValue {
  if (Number.isNaN(value) || value === undefined) throw new Error('This distribution has no defined value for the requested statistic.')
  if (!Number.isFinite(value)) return { exact: value > 0 ? '∞' : '−∞', mathml: `<math><mo>${value > 0 ? '∞' : '−∞'}</mo></math>` }
  const text = Number(value.toPrecision(12)).toString()
  return { exact: `≈ ${text}`, mathml: `<math><mo>≈</mo><mn>${text}</mn></math>` }
}

export function prepareProbability(relations: RelationAst[]) {
  const context = probabilityContext(relations)
  const declarations: Record<string, DisplayValue> = {}
  function transform(node: ExpressionAst): ExpressionAst {
    if (node.kind === 'call' && probabilityCalls.has(node.name)) {
      const value = context.evaluate(node)
      if (typeof value !== 'number' || !Number.isFinite(value)) throw new Error('This statistic is undefined or infinite; evaluate it as a standalone query.')
      return { kind: 'number', value: String(value) }
    }
    if (node.kind === 'call' && isDistribution(node.name)) throw new Error('Use a named distribution declaration or P, E, Var, quantile.')
    if (node.kind === 'symbol' && Object.keys(declarations).some(name => name.toLowerCase() === node.name.toLowerCase())) {
      throw new Error(`Use P, E, Var or quantile to evaluate random variable ${node.name}.`)
    }
    if (node.kind === 'array') return { ...node, items: node.items.map(transform) }
    if (node.kind === 'binary') return { ...node, left: transform(node.left), right: transform(node.right) }
    if (node.kind === 'unary' || node.kind === 'factorial') return { ...node, operand: transform(node.operand) }
    if (node.kind === 'call') return { ...node, args: node.args.map(transform) }
    return node
  }
  const remaining: RelationAst[] = []
  for (const row of relations) {
    if (context.isRandomDefinition(row) && row.kind === 'equation' && row.left.kind === 'symbol') {
      declarations[row.left.name] = { exact: toLatex(row.right), mathml: toMathMl(row.right) }
    } else remaining.push(row)
  }
  // Fully numeric probability work can run locally, without waiting for Python.
  if (remaining.every(row => row.kind === 'query')) {
    try {
      const queries = remaining.map(row => probabilityDisplay(numericOrInfinite(context.evaluate((row as Extract<RelationAst, { kind: 'query' }>).expression))))
      return { relations: [], finish: (result: SolverResult) => result, result: { status: 'solved', variables: Object.keys(declarations), solutions: [{ assignments: declarations, queries }] } as SolverResult }
    } catch (error) {
      if (remaining.every(row => row.kind === 'query' && containsProbability(row.expression))) throw error
    }
  }
  const transformed = remaining.map((row): RelationAst => row.kind === 'equation' ? { ...row, left: transform(row.left), right: transform(row.right) } : { ...row, expression: transform(row.expression) })
  return {
    relations: transformed,
    result: undefined,
    finish: (result: SolverResult): SolverResult => result.status === 'solved' ? { ...result, variables: [...Object.keys(declarations), ...result.variables], solutions: result.solutions.map(solution => ({
      ...solution,
      assignments: { ...declarations, ...solution.assignments },
      queries: solution.queries.map((value, index) => {
        const query = remaining.filter(row => row.kind === 'query')[index]
        const approximate = Number(value.approximate ?? value.exact)
        return query?.kind === 'query' && containsProbability(query.expression) && Number.isFinite(approximate) ? probabilityDisplay(approximate) : value
      }),
    })) } : result,
  }
}
function numericOrInfinite(value: Value): number { if (typeof value !== 'number') throw new Error('Use P, E, Var or quantile to evaluate a random variable.'); return value }

import type { Relation } from '@/registry/calculator/lib/model'
import type { PlotViewport, PlotCurve } from '@/registry/calculator/lib/plot'
import { probabilityContext, type ProbabilityEvent } from '@/registry/calculator/lib/probability'

export function prepareProbabilityPlot(relations: readonly Relation[], viewport?: PlotViewport) {
  const selected = relations.filter(row => row.enabled)
  const context = probabilityContext(selected.map(row => row.ast))
  const series = selected.flatMap(row => {
    const ast = row.ast
    let event: ProbabilityEvent | undefined
    if (context.isRandomDefinition(ast) && ast.kind === 'equation') {
      return [{ row, value: context.random(context.evaluate(ast.right)), event }]
    }
    if (ast.kind === 'query' && ast.expression.kind === 'call' && ast.expression.name === 'P') {
      event = context.event(ast.expression.args[0])
      if (!event.random) throw new Error('This event is deterministic and has no distribution to plot.')
      return [{ row, value: event.random, event }]
    }
    if (ast.kind === 'query') {
      const value = context.random(context.evaluate(ast.expression))
      return [{ row, value, event }]
    }
    // Numeric parameter definitions contribute context, not extra graph curves.
    if (ast.kind === 'equation' && ast.left.kind === 'symbol' && typeof context.evaluate(ast.right) === 'number') return []
    throw new Error('Select distribution declarations and P(event) queries together. Plot ordinary equations separately.')
  })
  if (!series.length) throw new Error('Select a distribution declaration or P(event) to plot.')
  if (series.some(s => s.value.distribution.discrete) && series.some(s => !s.value.distribution.discrete)) throw new Error('Plot discrete and continuous distributions separately: probability and density use different vertical scales.')
  const ranges = series.map(({ value: { distribution: d, scale, shift }, event }) => {
    const endpoints = [d.quantile(0.001), d.quantile(0.999)].map(x => scale * x + shift)
    if (event) endpoints.push(...event.boundaries.map(x => x * scale + shift))
    if (endpoints.some(x => !Number.isFinite(x))) throw new Error('Could not determine a finite plot range for these parameters.')
    return [Math.min(...endpoints), Math.max(...endpoints)]
  })
  const lower = Math.min(...ranges.map(r => r[0])), upper = Math.max(...ranges.map(r => r[1]))
  const padding = Math.max((upper - lower) * 0.06, upper === lower ? 1 : 0)
  const xRange: [number, number] = viewport?.x ?? [lower - padding, upper + padding]
  const curves: PlotCurve[] = series.map(({ row, value: { distribution: d, scale, shift }, event }) => {
    let xs: number[]
    if (d.discrete) {
      const baseBounds = xRange.map(x => (x - shift) / scale)
      const start = Math.max(d.support[0], Math.ceil(Math.min(...baseBounds)))
      const end = Math.min(d.support[1], Math.floor(Math.max(...baseBounds)))
      if (end - start > 2000) throw new Error('Too many discrete outcomes to display. Zoom in or use smaller distribution parameters.')
      xs = Array.from({ length: Math.max(0, end - start + 1) }, (_, i) => (start + i) * scale + shift).sort((a, b) => a - b)
    } else {
      xs = Array.from({ length: 501 }, (_, i) => xRange[0] + i / 500 * (xRange[1] - xRange[0]))
      const edges = (event?.boundaries ?? d.support.filter(Number.isFinite)).map(x => x * scale + shift)
      // Include both sides of event edges so shading stops at the actual cutoff.
      const epsilon = (xRange[1] - xRange[0]) * 1e-9
      xs.push(...edges.flatMap(x => event ? [x - epsilon, x, x + epsilon] : [x]).filter(x => x >= xRange[0] && x <= xRange[1]))
      xs.sort((a, b) => a - b)
    }
    const data = xs.map(x => {
      const base = (x - shift) / scale
      const y = d.pdf(base) / (d.discrete ? 1 : Math.abs(scale))
      return { x, y: Number.isFinite(y) ? y : null, shaded: event?.includes(base) && Number.isFinite(y) ? y : 0 }
    })
    return { id: row.id, label: event ? `${row.source} ≈ ${Number(event.probability.toPrecision(7))}` : row.source, data, discrete: d.discrete, shaded: !!event }
  })
  const peak = Math.max(0, ...curves.flatMap(curve => curve.data!.map(p => p.y ?? 0)))
  const suggested: PlotViewport = { x: xRange, y: [0, peak > 0 ? peak * 1.15 : 1] }
  return { curves, xLabel: 'value', yLabel: series[0].value.distribution.discrete ? 'probability' : 'density', viewport: viewport ?? suggested }
}

import { BUILTIN_ARITY } from '@/registry/calculator/lib/dsl/ast'
import { DISTRIBUTIONS } from '@/registry/calculator/lib/distributions'

const signatures: Record<string, readonly string[]> = {
  ...DISTRIBUTIONS,
  dot: ['u', 'v'], cross: ['u', 'v'], norm: ['vector'], unit: ['vector'],
  transpose: ['matrix'], det: ['matrix'], inv: ['matrix'], trace: ['matrix'], rank: ['matrix'], linsolve: ['matrix', 'vector'],
  grad: ['expression', 'variables'], jacobian: ['vector', 'variables'], div: ['vector', 'variables'], curl: ['vector', 'variables'], hessian: ['expression', 'variables'],
  P: ['event'], E: ['variable'], Var: ['variable'], quantile: ['variable', 'probability'],
  diff: ['expression', 'variable'], integrate: ['expression', 'variable'], limit: ['expression', 'variable', 'point'],
}
for (const name of Object.keys(BUILTIN_ARITY)) signatures[name] ??= ['expression']

export type Completion = { suffix: string; insertion: string; replaceFrom: number; signature: string }
export function completeFunction(source: string, caret: number): Completion | null {
  if (caret !== source.length) return null
  const prefix = source.match(/[A-Za-z][A-Za-z0-9]*$/)?.[0]
  if (!prefix) return null
  const names = Object.keys(signatures)
  const name = names.find(name => name === prefix) ?? names.find(name => name.startsWith(prefix)) ?? names.find(name => name.toLowerCase().startsWith(prefix.toLowerCase()))
  if (!name) return null
  const suffix = name.slice(prefix.length)
  return { suffix: `${suffix}(${signatures[name].join(', ')})`, insertion: `${name}(`, replaceFrom: source.length - prefix.length, signature: `${name}(${signatures[name].join(', ')})` }
}

export function functionHint(source: string, caret: number): string | null {
  const stack: { name: string; argument: number }[] = []
  const before = source.slice(0, caret)
  for (let i = 0; i < before.length; i++) {
    if (before[i] === '(' || before[i] === '{' || before[i] === '[') stack.push({ name: before.slice(0, i).match(/[A-Za-z][A-Za-z0-9]*$/)?.[0] ?? '', argument: 0 })
    else if (before[i] === ')' || before[i] === '}' || before[i] === ']') stack.pop()
    else if (before[i] === ',' && stack.length) stack[stack.length - 1].argument++
  }
  const current = stack.findLast(entry => entry.name !== '')
  if (!current) return null
  const args = signatures[current.name] ?? signatures[current.name.toLowerCase()]
  return args ? `${current.name}(${args.join(', ')}) — ${args[current.argument] ?? 'close with )'}` : null
}

'use client'

import { useRef, useState, type ReactNode } from 'react'

export type GridCell = {
  text: string
  title?: string
  readOnly?: boolean
  className?: string
  content?: ReactNode
  onActivate?: () => void
  onType?: (text: string) => void
}
export type GridRow = { id: string; cells: GridCell[] }
type Position = { row: number; column: number }

export function CellGrid({ label, columns, rows, widths, emptyMessage, onActiveCellChange }: {
  label: string
  columns: string[]
  rows: GridRow[]
  widths?: string[]
  emptyMessage?: string
  onActiveCellChange?: (row: number, column: number) => void
}) {
  const root = useRef<HTMLDivElement>(null)
  const [active, setActive] = useState<Position>({ row: 0, column: 0 })
  const [anchor, setAnchor] = useState<Position>(active)
  // Keep the keyboard entry point valid after a row is removed.
  const current = { row: Math.min(active.row, Math.max(0, rows.length - 1)), column: active.column }
  const start = { row: Math.min(anchor.row, current.row), column: Math.min(anchor.column, current.column) }
  const end = { row: Math.max(anchor.row, current.row), column: Math.max(anchor.column, current.column) }

  function select(position: Position, extend = false) {
    root.current?.querySelector<HTMLElement>(`[data-row="${position.row}"][data-column="${position.column}"]`)?.focus()
    setActive(position)
    setAnchor(extend ? anchor : position)
  }

  return (
    <div className="calculator-cell-grid" ref={root}>
      <table role="grid" aria-label={label} aria-multiselectable="true" onCopy={event => {
        if ((event.target as HTMLElement).closest('input, textarea')) return
        event.preventDefault()
        event.clipboardData.setData('text/plain', rows.slice(start.row, end.row + 1)
          .map(row => row.cells.slice(start.column, end.column + 1).map(cell => cell.text).join('\t')).join('\n'))
      }}>
        <colgroup><col style={{ width: '2.5rem' }} />{columns.map((column, index) => <col key={column} style={{ width: widths?.[index] }} />)}</colgroup>
        <thead><tr><th aria-label="Row" />{columns.map((column, index) => (
          <th scope="col" key={column}><span className="calculator-column-letter">{String.fromCharCode(65 + index)}</span>{column}</th>
        ))}</tr></thead>
        <tbody>
          {rows.map((row, rowIndex) => <tr key={row.id}>
            <th scope="row">{rowIndex + 1}</th>
            {row.cells.map((cell, columnIndex) => {
              const selected = rowIndex >= start.row && rowIndex <= end.row && columnIndex >= start.column && columnIndex <= end.column
              return <td key={columnIndex} role="gridcell" data-row={rowIndex} data-column={columnIndex}
                tabIndex={rowIndex === current.row && columnIndex === current.column ? 0 : -1}
                aria-readonly={cell.readOnly || undefined} className={cell.className}
                aria-selected={selected} aria-label={`${String.fromCharCode(65 + columnIndex)}${rowIndex + 1}: ${cell.text || 'Empty'}`}
                title={cell.title ?? cell.text} data-selected={selected || undefined}
                onFocus={event => {
                  if (event.target !== event.currentTarget) return
                  const position = { row: rowIndex, column: columnIndex }
                  setActive(position)
                  setAnchor(position)
                  onActiveCellChange?.(rowIndex, columnIndex)
                }}
                onClick={event => {
                  const position = { row: rowIndex, column: columnIndex }
                  if ((event.target as HTMLElement).closest('button, input')) {
                    setActive(position)
                    setAnchor(position)
                    onActiveCellChange?.(rowIndex, columnIndex)
                  } else select(position, event.shiftKey)
                }}
                onDoubleClick={event => {
                  if (!cell.readOnly && !(event.target as HTMLElement).closest('button, input')) cell.onActivate?.()
                }}
                onKeyDown={event => {
                  if (event.target !== event.currentTarget || event.nativeEvent.isComposing) return
                  const modifier = event.ctrlKey || event.metaKey
                  let next = { row: rowIndex, column: columnIndex }
                  switch (event.key) {
                    case 'ArrowUp': next.row--; break
                    case 'ArrowDown': next.row++; break
                    case 'ArrowLeft': next.column--; break
                    case 'ArrowRight': next.column++; break
                    case 'Home': next.column = 0; if (modifier) next.row = 0; break
                    case 'End': next.column = columns.length - 1; if (modifier) next.row = rows.length - 1; break
                    case 'Tab': {
                      const index = rowIndex * columns.length + columnIndex + (event.shiftKey ? -1 : 1)
                      if (index < 0 || index >= rows.length * columns.length) return
                      next = { row: Math.floor(index / columns.length), column: index % columns.length }
                      break
                    }
                    case 'Enter':
                    case 'F2':
                      event.preventDefault()
                      if (cell.readOnly) return
                      if (cell.onActivate) cell.onActivate()
                      else {
                        const button = event.currentTarget.querySelector<HTMLButtonElement>('button')
                        button?.focus()
                        button?.click()
                      }
                      return
                    default:
                      if (!cell.readOnly && !modifier && !event.altKey && event.key.length === 1 && cell.onType) {
                        event.preventDefault()
                        cell.onType(event.key)
                      }
                      return
                  }
                  event.preventDefault()
                  next = { row: Math.max(0, Math.min(rows.length - 1, next.row)), column: Math.max(0, Math.min(columns.length - 1, next.column)) }
                  select(next, event.shiftKey && event.key !== 'Tab')
                }}
              ><div className="calculator-cell-content">{cell.content ?? cell.text}</div></td>
            })}
          </tr>)}
          {rows.length === 0 && <tr><th scope="row">1</th>{columns.map(column => <td key={column} />)}</tr>}
        </tbody>
      </table>
      {rows.length === 0 && emptyMessage && <p className="p-3 text-xs text-muted-foreground">{emptyMessage}</p>}
    </div>
  )
}

import { collectEquationSymbols, collectFreeSymbols } from '@/registry/calculator/lib/dsl/analyze'
import { parseRelation } from '@/registry/calculator/lib/dsl/parser'
import type { RelationAst } from '@/registry/calculator/lib/dsl/ast'
import type { Relation, VariableInput } from '@/registry/calculator/lib/model'
import type { DisplayValue, SolverResult } from '@/registry/calculator/lib/solver/protocol'

export type VariableRow = VariableInput & {
  supplied: boolean
  generated: boolean
  locked: boolean
  values: DisplayValue[]
}

export function parseVariable(name: string, source: string): Pick<VariableInput, 'name' | 'source'> {
  name = name.trim()
  source = source.trim()
  if (name) {
    const parsed = parseRelation(name)
    if (parsed.kind !== 'query' || parsed.expression.kind !== 'symbol') {
      throw new Error('Use a variable name such as x or mass.')
    }
    name = name.toLowerCase()
  }
  if (source && parseRelation(source).kind !== 'query') {
    throw new Error('Enter a value or expression here. Put equations in the Equations grid.')
  }
  return { name, source }
}

export function workspaceRelations(equations: Relation[], variables: VariableInput[]): RelationAst[] {
  return [
    ...equations.filter(equation => equation.enabled).map(equation => equation.ast),
    ...variables.filter(variable => variable.source.trim()).map(variable =>
      parseRelation(variable.name ? `${variable.name} = ${variable.source}` : variable.source)),
  ]
}

export function variableRows(equations: Relation[], variables: VariableInput[], result?: SolverResult): VariableRow[] {
  const names = new Set(collectEquationSymbols(equations.filter(row => row.enabled).map(row => row.ast)))
  for (const variable of variables) {
    if (variable.name) names.add(variable.name)
    if (variable.source) {
      const ast = parseRelation(variable.source)
      if (ast.kind === 'query') for (const symbol of collectFreeSymbols(ast.expression)) names.add(symbol)
    }
  }
  const solutions = result?.status === 'solved' ? result.solutions : []
  const rows = [...names].map(name => {
    const input = variables.find(variable => variable.name === name)
    const supplied = Boolean(input?.source.trim())
    const values = solutions.map(solution => Object.hasOwn(solution.assignments, name) ? solution.assignments[name] : undefined).filter((value): value is DisplayValue => Boolean(value))
    return {
      id: input?.id ?? `symbol-${name}`, name, source: input?.source ?? '',
      supplied, generated: !input, locked: !supplied && values.length > 0 && values.length === solutions.length,
      values,
    }
  })
  let queryIndex = 0
  for (const input of variables.filter(variable => !variable.name)) {
    const values = input.source ? solutions.map(solution => solution.queries[queryIndex]).filter((value): value is DisplayValue => Boolean(value)) : []
    if (input.source) queryIndex++
    rows.push({ ...input, supplied: Boolean(input.source), generated: false, locked: false, values })
  }
  return rows
}
